package alphametics

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// errNoSolution is returned when a puzzle has no valid solution.
var errNoSolution = errors.New("no solution")

// Solve solves an alphametics puzzle of the form "WORD1 + WORD2 + ... == RESULT".
// It returns a mapping from each letter to a distinct digit such that the
// equation holds, or an error if no such mapping exists.
func Solve(puzzle string) (map[string]int, error) {
	addends, result, err := parse(puzzle)
	if err != nil {
		return nil, err
	}

	// Coefficient of each letter: the sum of its place values on the left
	// minus the sum on the right. A solution is any assignment of distinct
	// digits for which the weighted sum is exactly zero.
	coeffs := map[rune]int64{}
	leading := map[rune]bool{}
	accumulate(addends, 1, coeffs, leading)
	accumulate([]string{result}, -1, coeffs, leading)

	letters := make([]rune, 0, len(coeffs))
	for l := range coeffs {
		letters = append(letters, l)
	}
	if len(letters) > 10 {
		return nil, errNoSolution
	}

	// Assign the most heavily weighted letters first; their bounds prune
	// the search tree much more aggressively.
	sort.Slice(letters, func(i, j int) bool {
		return abs64(coeffs[letters[i]]) > abs64(coeffs[letters[j]])
	})

	weights := make([]int64, len(letters))
	noZero := make([]bool, len(letters))
	for i, l := range letters {
		weights[i] = coeffs[l]
		noZero[i] = leading[l]
	}

	assignment := make([]int, len(letters))
	used := make([]bool, 10)
	if !search(0, 0, letters, weights, noZero, assignment, used) {
		return nil, errNoSolution
	}

	solution := make(map[string]int, len(letters))
	for i, l := range letters {
		solution[string(l)] = assignment[i]
	}
	return solution, nil
}

// parse splits a puzzle like "A + BB == C" into its addends and result.
func parse(puzzle string) (addends []string, result string, err error) {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, "", fmt.Errorf("invalid puzzle %q: expected exactly one '=='", puzzle)
	}
	for _, w := range strings.Split(parts[0], "+") {
		word := strings.TrimSpace(w)
		if word == "" {
			return nil, "", fmt.Errorf("invalid puzzle %q: empty word", puzzle)
		}
		addends = append(addends, word)
	}
	result = strings.TrimSpace(parts[1])
	if result == "" {
		return nil, "", fmt.Errorf("invalid puzzle %q: empty result", puzzle)
	}
	return addends, result, nil
}

// accumulate adds sign * 10^place for every letter of every word into coeffs,
// and marks letters that start a multi-digit word in leading.
func accumulate(words []string, sign int, coeffs map[rune]int64, leading map[rune]bool) {
	for _, w := range words {
		if len(w) > 1 {
			leading[rune(w[0])] = true
		}
		place := int64(1)
		for i := len(w) - 1; i >= 0; i-- {
			coeffs[rune(w[i])] += sign * place
			place *= 10
		}
	}
}

// search assigns digits to letters[depth:] (in descending weight order) so
// that the weighted sum ends up exactly zero.
func search(depth int, sum int64, letters []rune, weights []int64, noZero, assignment []int, used []bool) bool {
	if depth == len(letters) {
		return sum == 0
	}

	// Prune: even with the best/worst remaining digits, the total cannot
	// reach zero.
	minRem, maxRem := remainingBounds(depth, weights, noZero, used)
	if sum+maxRem < 0 || sum+minRem > 0 {
		return false
	}

	for d := 0; d <= 9; d++ {
		if used[d] || (d == 0 && noZero[depth]) {
			continue
		}
		used[d] = true
		assignment[depth] = d
		if search(depth+1, sum+weights[depth]*int64(d), letters, weights, noZero, assignment, used) {
			return true
		}
		used[d] = false
	}
	return false
}

// remainingBounds reports the minimum and maximum total contribution the
// unassigned letters (index >= from) can still add, given the digits in use.
func remainingBounds(from int, weights []int64, noZero, used []bool) (min, max int64) {
	for i := from; i < len(weights); i++ {
		w := weights[i]
		if w == 0 {
			continue
		}
		lo, hi := 0, 9
		if noZero[i] {
			lo = 1
		}
		lo = firstAvailable(used, lo, hi, false)
		hi = firstAvailable(used, hi, lo, true)
		if lo > hi {
			return 0, 0 // no digits left for this letter; branch is dead
		}
		if w > 0 {
			min += w * int64(lo)
			max += w * int64(hi)
		} else {
			min += w * int64(hi)
			max += w * int64(lo)
		}
	}
	return min, max
}

// firstAvailable returns the smallest (ascending) or largest (descending)
// digit in [lo, hi] that is not in used.
func firstAvailable(used []bool, start, bound int, descending bool) int {
	if descending {
		for d := start; d >= bound; d-- {
			if !used[d] {
				return d
			}
		}
	} else {
		for d := start; d <= bound; d++ {
			if !used[d] {
				return d
			}
		}
	}
	return -1
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}
